                    if let Some(default) = default {
                        let arg_values = vec![default.to_os_string()];
                        let trailing_idx = None;
                        let _ = ok!(self.react(
                            None,
                            ValueSource::DefaultValue,
                            arg,
                            arg_values,
                            trailing_idx,
                            matcher,
                        ));
                    }
                    return Ok(());
                }
            }
        }
